const path = "D:\\lean\\tmp\\sheaf\\xif\\paper\\S1850RefuteS1756Actual.lean";
const r = await tools.pwsh({
  description: "File stats, forbidden tokens, olean, hash",
  command: `$p='${path}';
$lines=(Get-Content $p).Count; "LINES=$lines";
"FORBIDDEN:"; Select-String -Path $p -Pattern 'sorry|admit|native_decide|^axiom|by_contra!' | ForEach-Object { $_.LineNumber.ToString() + ': ' + $_.Line };
"OLEAN:"; Get-ChildItem -Path (Split-Path $p) -Filter 'S1850RefuteS1756Actual*' | Select-Object Name,Length,LastWriteTime | Format-Table -AutoSize;
$h=(Get-FileHash -Algorithm SHA256 $p); "SHA256=" + $h.Hash;`,
  workdir: "D:\\lean",
});
console.log(r.stdout.text);
console.log("ERR:", r.stderr.text.slice(0,1000));
", "description": "Check stats, forbidden tokens, olean and hash"}

